beforeExample:
import java.util.Collections;
import java.util.List;

public class Example {
    public void foo() {
        List<String> empty = java.util.Collections.emptyList();
        System.out.println("Hello");
    }
}

afterExample:
import static java.util.Collections.emptyList;

import java.util.List;

public class Example {
    public void foo() {
        List<String> empty = emptyList();
        System.out.println("Hello");
    }
}

negativeExample:
import java.util.List;

public class Example {
    public void bar(List<String> list) {
        // This should not be simplified as it's an instance method call
        list.size();
    }

    static class MyUtility {
        public static void doSomethingStatic() {}
        public void doSomethingNonStatic() {}
    }

    public void other() {
        // Non-static method, should not match
        MyUtility util = new MyUtility();
        util.doSomethingNonStatic();

        // MyUtility is a local type reference, not an FQN starting with its package.
        // The rule matches against fully qualified type names (e.g., java.util.Collections).
        MyUtility.doSomethingStatic();
    }
}
